	case MCPServerStartedMsg:
		return a.handleMCPServerStarted(msg)

	case mcpJobsRequestMsg:
		return a.handleMCPJobsRequest(msg)

	case mcpForwardsRequestMsg:
		return a.handleMCPForwardsRequest(msg)
